    milansoc_milansoc_vexiiriscv_interrupt = 32'd0;
    milansoc_milansoc_vexiiriscv_interrupt[2] = milansoc_milansoc_timer_irq;
    milansoc_milansoc_vexiiriscv_interrupt[1] = milansoc_milansoc_uart_core_irq;
