assign milansoc_milansoc_r_addr = (milansoc_milansoc_vexiiriscv_pbus_ar_payload_addr - 1'd0);
assign milansoc_milansoc_w_addr = (milansoc_milansoc_vexiiriscv_pbus_aw_payload_addr - 1'd0);
always @(*) begin
    milansoc_milansoc_adapted_interface_adr = 30'd0;
    milansoc_milansoc_adapted_interface_cyc = 1'd0;
    milansoc_milansoc_adapted_interface_dat_w = 32'd0;
    milansoc_milansoc_adapted_interface_sel = 4'd0;
    milansoc_milansoc_adapted_interface_stb = 1'd0;
    milansoc_milansoc_adapted_interface_we = 1'd0;
    milansoc_milansoc_data_axilite2wishbone_next_value1 = 32'd0;
    milansoc_milansoc_data_axilite2wishbone_next_value_ce1 = 1'd0;
    milansoc_milansoc_last_ar_aw_n_axilite2wishbone_next_value0 = 1'd0;
    milansoc_milansoc_last_ar_aw_n_axilite2wishbone_next_value_ce0 = 1'd0;
    milansoc_milansoc_vexiiriscv_pbus_ar_ready = 1'd0;
    milansoc_milansoc_vexiiriscv_pbus_aw_ready = 1'd0;
    milansoc_milansoc_vexiiriscv_pbus_b_payload_resp = 2'd0;
    milansoc_milansoc_vexiiriscv_pbus_b_valid = 1'd0;
    milansoc_milansoc_vexiiriscv_pbus_r_payload_data = 32'd0;
    milansoc_milansoc_vexiiriscv_pbus_r_payload_resp = 2'd0;
    milansoc_milansoc_vexiiriscv_pbus_r_valid = 1'd0;
    milansoc_milansoc_vexiiriscv_pbus_w_ready = 1'd0;
    socbushandler0_axilite2wishbone_next_state = 3'd0;
    socbushandler0_axilite2wishbone_next_state = socbushandler0_axilite2wishbone_state;
    case (socbushandler0_axilite2wishbone_state)
        1'd1: begin
            milansoc_milansoc_adapted_interface_stb = 1'd1;
            milansoc_milansoc_adapted_interface_cyc = 1'd1;
            milansoc_milansoc_adapted_interface_adr = milansoc_milansoc_r_addr[31:2];
            milansoc_milansoc_adapted_interface_sel = 4'd15;
            if (milansoc_milansoc_adapted_interface_ack) begin
                milansoc_milansoc_vexiiriscv_pbus_ar_ready = 1'd1;
                milansoc_milansoc_data_axilite2wishbone_next_value1 = milansoc_milansoc_adapted_interface_dat_r;
                milansoc_milansoc_data_axilite2wishbone_next_value_ce1 = 1'd1;
                socbushandler0_axilite2wishbone_next_state = 2'd2;
            end
        end
        2'd2: begin
            milansoc_milansoc_vexiiriscv_pbus_r_valid = 1'd1;
